                        : (roomPerformanceRows.length > 0 ? roomPerformanceRows.map((room, index) => {
                          const occupancyRate = Number(room.occupancy_rate || 0);
                          const statusMeta = getPerformanceStatus(occupancyRate);
                          const monthlyRevenueValue = Number(room.revenue ?? room.monthly_revenue ?? 0);
                          const incomePerRoomValue = Number(room.revpar ?? room.income_per_room ?? 0);

                          return (
                            <tr key={room.id || index} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                              <td className="px-6 py-4">
                                <a
                                  href="/rooms"
                                  className="font-medium text-emerald-600 dark:text-emerald-400 hover:underline"
                                >
                                  {room.name || room.room_name || room.room_number || `Room ${index + 1}`}
                                </a>
                              </td>
                              <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                  <div className="w-16 h-2 bg-gray-100 rounded-full overflow-hidden">
                                    <div
                                      className={`h-full rounded-full ${occupancyRate >= 80 ? 'bg-green-500' : occupancyRate >= 50 ? 'bg-blue-500' : 'bg-orange-500'}`}
                                      style={{ width: `${occupancyRate}%` }}
                                    />
                                  </div>
                                  <span className="text-gray-600 dark:text-gray-300">{occupancyRate}%</span>
                                </div>
                              </td>
                              <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{Number(room.capacity || 0)}</td>
                              <td className="px-6 py-4 font-semibold text-gray-900 dark:text-white">{formatPrice(monthlyRevenueValue)}</td>
                              <td className="px-6 py-4 text-gray-900 dark:text-white font-medium">{formatPrice(incomePerRoomValue)}</td>                              <td className="px-6 py-4">
                                <span className={`px-2.5 py-2 rounded-full text-xs font-semibold ${statusMeta.className}`}>
                                  {statusMeta.label}
                                </span>
                              </td>
                            </tr>
                          );
                        }) : (
                          <tr>
                            <td className="px-6 py-6 text-gray-500 dark:text-gray-400" colSpan={6}>
                              No room performance data available.
                            </td>
                          </tr>
                        ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          ) : (
            <div className="flex justify-center py-20"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600"></div></div>
          )
        ) : (!loading && !propertiesLoading && properties !== null) ? (
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-12 text-center">
            <div className="w-20 h-20 bg-gray-100 dark:bg-gray-700 rounded-full mx-auto flex items-center justify-center mb-6">
              <Building2 className="w-10 h-10 text-gray-500" />
            </div>
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-2">No Properties Yet</h3>
            <p className="text-gray-500 dark:text-gray-400 mb-6 max-w-md mx-auto">Start by adding your first property to see analytics data.</p>
            <a href="/properties" className="inline-flex items-center gap-2 px-6 py-4 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium transition-colors">
              <Home className="w-5 h-5" /> Add Your First Property
            </a>
          </div>
        ) : (
          <AnalyticsSkeleton />
        )}
      </div>

      {showExportModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 px-4" onClick={() => setShowExportModal(false)}>
          <div
            className="w-full max-w-md bg-white dark:bg-gray-800 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 p-6"
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Export CSV</h3>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Period Type</label>
                <select
                  value={exportConfig.granularity}
                  onChange={(e) => {
                    const nextGranularity = e.target.value;
                    setExportConfig((prev) => ({
                      ...prev,
                      granularity: nextGranularity,
                      weekInMonth: 1,
                    }));
                  }}
                  className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 px-3 py-2 text-sm text-gray-900 dark:text-white"
                >
                  <option value="week">Weekly</option>
                  <option value="month">Monthly</option>
                  <option value="year">Yearly</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Year</label>
                <select
                  value={exportConfig.year}
                  onChange={(e) => setExportConfig((prev) => ({ ...prev, year: Number(e.target.value), weekInMonth: 1 }))}
                  className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 px-3 py-2 text-sm text-gray-900 dark:text-white"
                >
                  {[...Array(7)].map((_, idx) => {
                    const year = new Date().getFullYear() - 5 + idx;
                    return <option key={year} value={year}>{year}</option>;
                  })}
                </select>
              </div>

              {exportConfig.granularity !== 'year' && (
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Month</label>
                  <select
                    value={exportConfig.month}
                    onChange={(e) => setExportConfig((prev) => ({ ...prev, month: Number(e.target.value), weekInMonth: 1 }))}
                    className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 px-3 py-2 text-sm text-gray-900 dark:text-white"
                  >
                    {monthNames.map((name, index) => (
                      <option key={name} value={index + 1}>{name}</option>
                    ))}
                  </select>
                </div>
              )}

              {exportConfig.granularity === 'week' && (
                <div>
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Week in Month</label>
                  <select
                    value={exportConfig.weekInMonth}
                    onChange={(e) => setExportConfig((prev) => ({ ...prev, weekInMonth: Number(e.target.value) }))}
                    className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 px-3 py-2 text-sm text-gray-900 dark:text-white"
                  >
                    {[...Array(getWeeksInMonth(exportConfig.year, exportConfig.month))].map((_, idx) => (
                      <option key={idx + 1} value={idx + 1}>Week {idx + 1}</option>
                    ))}
                  </select>
                </div>
              )}
            </div>

            <div className="mt-6 flex items-center justify-end gap-3">
              <button
                onClick={() => setShowExportModal(false)}
                className="px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-600 text-sm font-semibold text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-700"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmExport}
                disabled={loading || !analytics}
                className="px-4 py-2 rounded-lg bg-green-600 hover:bg-green-700 disabled:opacity-50 text-white text-sm font-semibold"
              >
                Export CSV
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Eye, X, CheckCircle, XCircle, Calendar, Search, Plus, Loader2, Clock, Edit3, Shuffle, Check, RefreshCw, CalendarDays, Calculator, Users, UserPlus } from 'lucide-react';
import AddBookingModal from './AddBookingModal';
import { showSuccess, showError, showLoading } from '../../utils/toast';
import PriceRow from '../../components/Shared/PriceRow';
import bookingService from '../../services/bookingService';
import { SkeletonStatCard, SkeletonTableRow } from '../../components/Shared/Skeleton';
import { useUIState } from '../../contexts/UIStateContext';
import { LANDLORD_MUTATION_FRESHNESS, refreshAfterMutation } from '../../utils/mutationFreshness';

export default function Bookings({ user, accessRole = 'landlord' }) {
  const location = useLocation();
  const navigate = useNavigate();
  const { uiState, updateData, invalidateData } = useUIState();
  const cachedData = uiState.data?.landlord_bookings;

  const normalizedRole = accessRole || user?.role || 'landlord';
  const isCaretaker = normalizedRole === 'caretaker';
  const caretakerPermissions = user?.caretaker_permissions || {};

  const normalizePermissionValue = (value) => {
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'allowed';
    }

    return Boolean(value);
  };

  const buildPermissionCandidates = (key, aliases = []) => {
    const base = String(key || '').trim();
    const singular = base.endsWith('ies')
      ? `${base.slice(0, -3)}y`
      : base.endsWith('s')
        ? base.slice(0, -1)
        : base;
    const plural = base.endsWith('s')
      ? base
      : singular === 'property'
        ? 'properties'
        : `${singular}s`;

    const keys = new Set([base, singular, plural, ...aliases]);
    const expanded = [];

    keys.forEach((entry) => {
      if (!entry) return;
      expanded.push(entry, `can_view_${entry}`, `can_manage_${entry}`);
    });

    return expanded;
  };

  const hasCaretakerPermission = (key, aliases = []) => {
    if (!isCaretaker) return true;

    return buildPermissionCandidates(key, aliases).some((candidate) =>
      normalizePermissionValue(caretakerPermissions?.[candidate]),
    );
  };

  const canApproveBookings = hasCaretakerPermission('approve_bookings', ['approve_booking']);
  const canCancelBookings = hasCaretakerPermission('cancel_bookings', ['cancel_booking']);
  const canManageBookings = canApproveBookings || canCancelBookings;
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [bookings, setBookings] = useState(cachedData?.bookings || []);
  const [stats, setStats] = useState(cachedData?.stats || { total: 0, confirmed: 0, pending: 0, completed: 0 });
  const [loading, setLoading] = useState(!cachedData);
  const [__error, setError] = useState('');
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [showFinalizeModal, setShowFinalizeModal] = useState(false);
  const [showConvertModal, setShowConvertModal] = useState(false);
  const [occupantToConvert, setOccupantToConvert] = useState(null);
  const [convertEmail, setConvertEmail] = useState('');
  const [processing, setProcessing] = useState(false);
  const [cancellationData, setCancellationData] = useState({ reason: '', refundAmount: 0, shouldRefund: false });
  const [showAddBookingModal, setShowAddBookingModal] = useState(false);
  const [extensionRequests, setExtensionRequests] = useState([]);
  const [loadingExtensions, setLoadingExtensions] = useState(false);
  const [transferRequests, setTransferRequests] = useState([]);
  const [loadingTransfers, setLoadingTransfers] = useState(false);
  const [, setDrilldownApplied] = useState(false);
  const [depositSettlementHistory, setDepositSettlementHistory] = useState([]);
  const [loadingDepositSettlementHistory, setLoadingDepositSettlementHistory] = useState(false);
  const [submittingDepositSettlement, setSubmittingDepositSettlement] = useState(false);
  const [depositSettlementForm, setDepositSettlementForm] = useState({
    damageFee: '',
    cleaningFee: '',
    otherFee: '',
    markRefunded: false,
    refundMethod: '',
    refundReference: '',
    note: ''
  });

  const resetDepositSettlementState = () => {
    setDepositSettlementHistory([]);
    setLoadingDepositSettlementHistory(false);
    setSubmittingDepositSettlement(false);
    setDepositSettlementForm({
      damageFee: '',
      cleaningFee: '',
      otherFee: '',
      markRefunded: false,
      refundMethod: '',
      refundReference: '',
      note: ''
    });
  };

  const closeDetailModal = () => {
    setShowDetailModal(false);
    setShowFinalizeModal(false);
    setSelectedBooking(null);
    resetDepositSettlementState();
    // Clear bookingId from URL when closing modal
    const params = new URLSearchParams(location.search);
    if (params.has('bookingId')) {
      params.delete('bookingId');
      navigate({ search: params.toString() }, { replace: true });
    }
  };

  const refreshLandlordMutationViews = () => {
    refreshAfterMutation({
      invalidateData,
      ...LANDLORD_MUTATION_FRESHNESS,
    });
  };

  const guardAnyBookingAction = () => {
    if (canManageBookings) return false;
    showError('Caretaker booking actions are disabled.');
    return true;
  };

  const guardApprovalAction = () => {
    if (canApproveBookings) return false;
    showError('You do not have approval permission for this booking action.');
    return true;
  };

  const guardCancellationAction = () => {
    if (canCancelBookings) return false;
    showError('You do not have cancellation permission for this booking action.');
    return true;
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Open-ended';

    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const canShowDepositSettlement = (booking) => {
    const status = String(booking?.status || '').toLowerCase();
    return ['confirmed', 'partial-completed', 'partial_completed', 'completed', 'cancelled', 'transferred'].includes(status);
  };

  const handleRefresh = async () => {
    await Promise.all([
      fetchBookings(),
      fetchStats(),
      fetchExtensions(),
      fetchTransfers()
    ]);
  };

  useEffect(() => {
    const params = new URLSearchParams(location.search || '');
    const nextStatus = params.get('status');
    const nextSearch = params.get('search');

    if (nextStatus) {
      setFilterStatus(nextStatus);
    }

    if (nextSearch !== null) {
      setSearchQuery(nextSearch);
    }

    setDrilldownApplied(false);
  }, [location.search]);

  const fetchBookings = useCallback(async () => {
    try {
      if (!uiState.data?.landlord_bookings) setLoading(true);
      const response = await bookingService.getBookings();
      if (response.success) {
        const list = response.data?.items || (Array.isArray(response.data) ? response.data : (Array.isArray(response.data?.data) ? response.data.data : []));
        setBookings(list);
        updateData('landlord_bookings', prev => ({ ...prev, bookings: list }));
        setError(null);
      } else if (response.status === 404 || response.status === 204) {
        setBookings([]);
        setError(null);
      } else {
        setBookings([]);
        setError(response.error || 'Failed to fetch bookings');
      }
    } catch (err) {
      if (err.response?.status === 404 || err.response?.status === 204) setBookings([]);
      else setError(err.response?.data?.message || 'Failed to fetch bookings');
    } finally { setLoading(false); }
  }, [updateData]);

  const fetchStats = useCallback(async () => {
    try {
      const response = await bookingService.getStats();
      if (response.success) {
        const data = response.data || { total: 0, confirmed: 0, pending: 0, completed: 0 };
        setStats(data);
        updateData('landlord_bookings', prev => ({ ...prev, stats: data }));
      }
    } catch (err) { console.error('Error fetching stats:', err); }
  }, [updateData]);

  const fetchExtensions = useCallback(async () => {
    try {
      setLoadingExtensions(true);
      const response = await bookingService.getExtensions();
      if (response.success) {
        const list = Array.isArray(response.data)
          ? response.data
          : (Array.isArray(response.data?.data) ? response.data.data : []);
        setExtensionRequests(list);
      } else {
        setExtensionRequests([]);
      }
    } catch (err) {
      console.error('Error fetching extensions:', err);
    } finally {
      setLoadingExtensions(false);
    }
  }, []);

  const fetchTransfers = useCallback(async () => {
    try {
      setLoadingTransfers(true);
      const response = await bookingService.getTransfers();
      if (response.success) {
        const list = Array.isArray(response.data)
          ? response.data
          : (Array.isArray(response.data?.data) ? response.data.data : []);
        setTransferRequests(list);
      } else {
        setTransferRequests([]);
      }
    } catch (err) {
      console.error('Error fetching transfers:', err);
    } finally {
      setLoadingTransfers(false);
    }
  }, []);

  useEffect(() => {
    fetchBookings();
    fetchStats();
    fetchExtensions();
    fetchTransfers();

    const handleOpenAdd = () => setShowAddBookingModal(true);
    window.addEventListener('open-add-booking', handleOpenAdd);
    return () => window.removeEventListener('open-add-booking', handleOpenAdd);
  }, [fetchBookings, fetchStats, fetchExtensions, fetchTransfers]);

  const handleHandleExtension = async (id, action, modifyData = null) => {
    if (guardAnyBookingAction()) return;
    const toastId = showLoading(`${action === 'modify' ? 'Modifying' : 'Updating'} request...`);
    try {
      const response = await bookingService.handleExtension(id, action, modifyData || {});
      if (!response.success) {
        throw new Error(response.error || 'Failed to handle request');
      }
      showSuccess(`Request ${action === 'modify' ? 'modified' : action} successfully!`, toastId);
      refreshLandlordMutationViews();
      fetchExtensions();
      fetchBookings(); // Refresh bookings to reflect new dates
    } catch (err) {
      console.error('Error handling extension:', err);
      showError(err.response?.data?.message || 'Failed to handle request', toastId);
    }
  };

  const handleHandleTransfer = async (id, action, transferData = null) => {
    if (guardAnyBookingAction()) return;
    const toastId = showLoading(`${action === 'approve' ? 'Approving' : 'Rejecting'} transfer...`);
    try {
      const response = await bookingService.handleTransfer(id, action, transferData || {});
      if (!response.success) {
        throw new Error(response.error || 'Failed to handle transfer');
      }
      showSuccess(`Transfer ${action}d successfully!`, toastId);
      refreshLandlordMutationViews();
      fetchTransfers();
      fetchBookings(); // Refresh bookings to reflect new room
    } catch (err) {
      console.error('Error handling transfer:', err);
      showError(
        err.response?.data?.message ||
        err.response?.data?.error ||
        'Failed to handle transfer',
        toastId
      );
    }
  };

  const handleUpdateStatus = async (bookingId, newStatus, cancellationReason = null, refundData = null) => {
    const normalizedStatus = String(newStatus || '').toLowerCase();
    if (normalizedStatus === 'cancelled') {
      if (guardCancellationAction()) return;
    } else if (guardApprovalAction()) {
      return;
    }

    const activeBooking = selectedBooking?.id === bookingId
      ? selectedBooking
      : bookings.find((booking) => booking.id === bookingId);

    if (newStatus === 'completed' && Number(activeBooking?.deposit_balance || 0) > 0) {
      showError(`Settle the deposit balance (₱${Number(activeBooking.deposit_balance).toLocaleString()}) before completing this booking.`);
      return;
    }

    const toastId = showLoading(`${newStatus === 'cancelled' ? 'Cancelling' : 'Updating'} booking...`);
    setProcessing(true);
    try {
      const response = await bookingService.updateStatus(bookingId, newStatus, {
        cancellation_reason: cancellationReason,
        refund_amount: refundData?.refundAmount || 0,
        should_refund: refundData?.shouldRefund || false,
      });
      if (!response.success) {
        throw new Error(response.error || 'Failed to update booking status');
      }

      refreshLandlordMutationViews();
      await fetchBookings();
      await fetchStats();
      closeDetailModal();
      setShowCancelModal(false);

      if (newStatus === 'cancelled' && refundData?.shouldRefund) {
        const refundedAmount = Number(refundData?.refundAmount || 0);
        const amountLabel = refundedAmount > 0
          ? ` (₱${refundedAmount.toLocaleString()})`
          : '';
        showSuccess(`Booking cancelled and refund sent to tenant${amountLabel}.`, toastId);
      } else {
        showSuccess(`Booking ${newStatus} successfully!`, toastId);
      }
    } catch (err) {
      console.error('Error updating status:', err);
      showError(err.message || err.response?.data?.message || 'Failed to update booking status', toastId);
    } finally {
      setProcessing(false);
    }
  };

  const handleApproveReservation = async (bookingId) => {
    if (guardApprovalAction()) return;
    const toastId = showLoading('Approving reservation...');
    setProcessing(true);
    try {
      const response = await bookingService.approveReservation(bookingId);
      if (!response.success) {
        throw new Error(response.error || 'Failed to approve reservation');
      }
      refreshLandlordMutationViews();
      showSuccess('Reservation approved!', toastId);
      await fetchBookings();
      await fetchStats();
      closeDetailModal();
    } catch (err) {
      showError(err.message || err.response?.data?.message || 'Failed to approve reservation', toastId);
    } finally {
      setProcessing(false);
    }
  };

  const handleCheckInTenant = async (bookingId) => {
    if (guardApprovalAction()) return;
    const toastId = showLoading('Checking in tenant...');
    setProcessing(true);
    try {
      const response = await bookingService.checkIn(bookingId);
      if (!response.success) {
        throw new Error(response.error || 'Failed to check in tenant');
      }
      refreshLandlordMutationViews();
      showSuccess('Tenant checked in successfully!', toastId);
      await fetchBookings();
      await fetchStats();
      closeDetailModal();
    } catch (err) {
      showError(err.message || err.response?.data?.message || 'Failed to check in tenant', toastId);
    } finally {
      setProcessing(false);
    }
  };


  const handleUpdatePayment = async (bookingId, paymentStatus) => {
    if (paymentStatus === 'refunded') {
      if (guardCancellationAction()) return;
    } else if (guardApprovalAction()) {
      return;
    }
    try {
      const response = await bookingService.recordPayment(bookingId, {
        payment_status: paymentStatus
      });
      if (!response.success) {
        throw new Error(response.error || 'Failed to update payment status');
      }

      const result = response.data || {};

      refreshLandlordMutationViews();

      // Refresh bookings list
      await fetchBookings();

      // Update the selected booking in the modal with the response data
      if (selectedBooking && selectedBooking.id === bookingId) {
        setSelectedBooking(prev => ({
          ...prev,
          paymentStatus: result.booking?.payment_status || paymentStatus,
          status: result.booking?.status || prev.status // Update status too in case it changed
        }));
      }

      // Show appropriate message
      if (result.completion_blocked) {
        showSuccess(result.message || 'Payment updated, but deposit must be settled before completion.');
      } else if (result.status_upgraded) {
        showSuccess('Payment updated! Booking automatically upgraded to Completed.');
      } else if (paymentStatus === 'refunded') {
        showSuccess(result.message || 'Tenant payment was marked as refunded.');
      } else {
        showSuccess(result.message || 'Payment status updated!');
      }
    } catch (err) {
      console.error('Error updating payment:', err);
      showError(err.message || err.response?.data?.message || 'Failed to update payment status');
    }
  };

  const handleFinalizeCheckout = async (bookingId, payload = {}) => {
    if (guardApprovalAction()) return;

    if (!bookingId) {
      showError('Unable to finalize checkout: booking reference is missing.');
      return;
    }

    const activeBooking = selectedBooking?.id === bookingId
      ? selectedBooking
      : bookings.find((booking) => booking.id === bookingId);

    if (!activeBooking) {
      showError('Unable to finalize checkout: booking details are unavailable.');
      return;
    }

    const status = String(activeBooking?.status || '').toLowerCase();
    if (!['confirmed', 'partial-completed', 'partial_completed'].includes(status)) {
      showError('Checkout can only be finalized for confirmed stays.');
      return;
    }

    // Validate deposit balance before proceeding
    if (Number(activeBooking?.deposit_balance || 0) > 0) {
      showError(`Please settle the deposit balance of ₱${Number(activeBooking.deposit_balance).toLocaleString()} before finalizing checkout.`);
      return;
    }

    const toastId = showLoading('Finalizing checkout...');
    setProcessing(true);
    try {
      const response = await bookingService.finalizeCheckout(bookingId, payload);
      if (!response.success) {
        throw new Error(response.error || 'Failed to finalize checkout');
      }

      refreshLandlordMutationViews();
      await fetchBookings();
      await fetchStats();
      setShowFinalizeModal(false);
      closeDetailModal();

      showSuccess(response.message || 'Checkout finalized successfully.', toastId);
    } catch (err) {
      console.error('Error finalizing checkout:', err);
      showError(err.message || err.response?.data?.message || 'Failed to finalize checkout', toastId);
    } finally {
      setProcessing(false);
    }
  };

  const handleOpenCancelModal = (booking) => {
    if (guardCancellationAction()) return;
    setSelectedBooking(booking);
    setCancellationData({
      reason: '',
      refundAmount: 0,
      shouldRefund: false
    });
    setShowCancelModal(true);
  };

  const handleOpenFinalizeModal = (booking) => {
    if (guardApprovalAction()) return;

    if (!booking?.id) {
      showError('Unable to finalize checkout: booking details are unavailable.');
      return;
    }

    if (Number(booking?.deposit_balance || 0) > 0) {
      showError(`Please settle the deposit balance of ₱${Number(booking.deposit.balance).toLocaleString()} before finalizing checkout.`);
      return;
    }

    setSelectedBooking(booking);
    setShowFinalizeModal(true);
  };

  const fetchDepositSettlementHistory = useCallback(async (bookingId, showErrorFlag = true) => {
    try {
      setLoadingDepositSettlementHistory(true);
      const response = await bookingService.getDepositSettlements(bookingId);
      if (!response.success) {
        throw new Error(response.error || 'Failed to fetch deposit settlement history');
      }
      const payload = response.data || {};
      const settlements = Array.isArray(payload.settlements) ? payload.settlements : [];
      const latestBalance = Number(payload.deposit_balance || 0);

      setDepositSettlementHistory(settlements);
      setSelectedBooking((prev) => (
        prev && prev.id === bookingId
          ? { ...prev, deposit_balance: latestBalance }
          : prev
      ));
      setBookings((prev) => prev.map((booking) => (
        booking.id === bookingId
          ? { ...booking, deposit_balance: latestBalance }
          : booking
      )));
    } catch (err) {
      if (showErrorFlag) {
        showError(err.message || err.response?.data?.message || 'Failed to fetch deposit settlement history');
      }
    } finally {
      setLoadingDepositSettlementHistory(false);
    }
  }, []);

  const handleOpenDetailModal = useCallback(async (booking) => {
    setSelectedBooking(booking);
    setShowDetailModal(true);
    resetDepositSettlementState();
    if (canShowDepositSettlement(booking)) {
      await fetchDepositSettlementHistory(booking.id, false);
    }
  }, [fetchDepositSettlementHistory]);

  useEffect(() => {
    const params = new URLSearchParams(location.search || '');
    const bookingId = params.get('bookingId');

    if (!bookingId || bookings.length === 0) {
      return;
    }

    setDrilldownApplied((prevApplied) => {
      if (prevApplied) return true; // already applied

      const targetBooking = bookings.find((booking) => String(booking.id) === String(bookingId));
      if (targetBooking) {
        handleOpenDetailModal(targetBooking);
        return true;
      }

      return false;
    });
  }, [location.search, bookings, handleOpenDetailModal]);

  const handleDepositSettlementInput = (field, value) => {
    setDepositSettlementForm((prev) => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSettleDeposit = async () => {
    if (guardApprovalAction()) return;
    if (!selectedBooking) return;

    const damageFee = Number.parseFloat(depositSettlementForm.damageFee) || 0;
    const cleaningFee = Number.parseFloat(depositSettlementForm.cleaningFee) || 0;
    const otherFee = Number.parseFloat(depositSettlementForm.otherFee) || 0;
    const markRefunded = Boolean(depositSettlementForm.markRefunded);
    const totalDeductions = damageFee + cleaningFee + otherFee;

    if (totalDeductions <= 0 && !markRefunded) {
      showError('Add a deduction or mark the remaining balance as refunded.');
      return;
    }

    if (markRefunded && !depositSettlementForm.refundMethod.trim()) {
      showError('Refund method is required when marking as refunded.');
      return;
    }

    try {
      setSubmittingDepositSettlement(true);
      const response = await bookingService.createDepositSettlement(selectedBooking.id, {
        damage_fee: damageFee,
        cleaning_fee: cleaningFee,
        other_fee: otherFee,
        mark_refunded: markRefunded,
        refund_method: markRefunded ? depositSettlementForm.refundMethod.trim() : null,
        refund_reference: markRefunded && depositSettlementForm.refundReference.trim()
          ? depositSettlementForm.refundReference.trim()
          : null,
        note: depositSettlementForm.note.trim() || null
      });
      if (!response.success) {
        throw new Error(response.error || 'Failed to settle deposit');
      }

      const payload = response.data || {};
      const updatedBalance = Number(payload.deposit_balance || 0);
      const latestSettlement = payload.settlement || null;

      setSelectedBooking((prev) => (
        prev && prev.id === selectedBooking.id
          ? { ...prev, deposit_balance: updatedBalance }
          : prev
      ));
      setBookings((prev) => prev.map((booking) => (
        booking.id === selectedBooking.id
          ? { ...booking, deposit_balance: updatedBalance }
          : booking
      )));

      if (latestSettlement) {
        setDepositSettlementHistory((prev) => [latestSettlement, ...prev]);
      } else {
        await fetchDepositSettlementHistory(selectedBooking.id, false);
      }

      setDepositSettlementForm({
        damageFee: '',
        cleaningFee: '',
        otherFee: '',
        markRefunded: false,
        refundMethod: '',
        refundReference: '',
        note: ''
      });

      refreshLandlordMutationViews();
      showSuccess('Deposit settlement recorded successfully.');
    } catch (err) {
      showError(err.message || err.response?.data?.message || 'Failed to settle deposit.');
    } finally {
      setSubmittingDepositSettlement(false);
    }
  };

  const handleCancelConfirm = () => {
    if (guardCancellationAction()) return;
    if (!cancellationData.reason.trim()) {
      showError('Please provide a cancellation reason');
      return;
    }

    if (cancellationData.shouldRefund && cancellationData.refundAmount <= 0) {
      showError('Please enter a valid refund amount');
      return;
    }

    handleUpdateStatus(
      selectedBooking.id,
      'cancelled',
      cancellationData.reason,
      cancellationData.shouldRefund ? {
        refundAmount: cancellationData.refundAmount,
        shouldRefund: true
      } : null
    );
  };

  const handleConvertOccupant = async () => {
    if (!occupantToConvert) return;
    if (!convertEmail.trim()) {
      showError('Email is required');
      return;
    }

    setProcessing(true);
    const toastId = showLoading('Registering occupant as tenant...');
    try {
      const response = await bookingService.convertOccupantToTenant(selectedBooking.id, occupantToConvert.id, {
        email: convertEmail.trim()
      });
      if (!response.success) {
        throw new Error(response.error || 'Failed to convert occupant');
      }

      showSuccess(response.message || 'Occupant registered as tenant successfully!', toastId);
      setShowConvertModal(false);
      setOccupantToConvert(null);
      setConvertEmail('');

      // Refresh data
      refreshLandlordMutationViews();
      await fetchBookings();
      // Reload booking detail explicitly to update occupant list
      const updatedBookingRes = await bookingService.getBookings();
      if (updatedBookingRes.success) {
        const list = Array.isArray(updatedBookingRes.data)
          ? updatedBookingRes.data
          : (Array.isArray(updatedBookingRes.data?.data) ? updatedBookingRes.data.data : []);
        const updatedBooking = list.find(b => b.id === selectedBooking.id);
        if (updatedBooking) {
          setSelectedBooking(updatedBooking);
        }
      }
    } catch (err) {
      showError(err.message || err.response?.data?.message || 'Failed to convert occupant', toastId);
    } finally {
      setProcessing(false);
    }
  };

  const filteredBookings = bookings.filter(booking => {
    if (filterStatus !== 'all' && booking.status !== filterStatus) return false;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      const searchableFields = [booking.guestName, booking.email, booking.roomNumber?.toString(), booking.propertyTitle, booking.bookingReference];
      return searchableFields.some(f => f?.toLowerCase().includes(query));
    }
    return true;
  });

  const getStatusColor = (s) => {
    switch (s) {
      case 'confirmed': return 'bg-green-100 text-green-800';
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'pending_reservation': return 'bg-orange-100 text-orange-800';
      case 'reserved': return 'bg-teal-100 text-teal-800';
      case 'completed': return 'bg-blue-100 text-blue-800';
      case 'cancelled': return 'bg-red-100 text-red-800';
      case 'transferred': return 'bg-indigo-100 text-indigo-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPaymentColor = (s) => {
    switch (s) {
      case 'paid': return 'bg-green-100 text-green-800';
      case 'partial': return 'bg-yellow-100 text-yellow-800';
      case 'unpaid': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const resolveBedCount = (booking) => {
    const value = Number(booking?.bedCount ?? booking?.bed_count ?? 1);
    return Number.isFinite(value) && value > 0 ? Math.floor(value) : 1;
  };

  const resolveOccupantCount = (booking) => {
    const explicit = Number(booking?.occupantCount ?? booking?.occupant_count ?? 0);
    if (Number.isFinite(explicit) && explicit > 0) {
      return Math.floor(explicit);
    }

    const loadedOccupantsCount = Array.isArray(booking?.occupants) ? booking.occupants.length : 0;
    if (loadedOccupantsCount > 0) {
      return loadedOccupantsCount;
    }

    const mode = String(booking?.bookingMode ?? booking?.booking_mode ?? 'normal').toLowerCase();
    return mode === 'proxy' ? resolveBedCount(booking) : 1;
  };

  const resolveRoomCapacity = (booking) => {
    const value = Number(booking?.room?.capacity ?? booking?.room_capacity ?? booking?.capacity ?? 0);
    return Number.isFinite(value) && value > 0 ? Math.floor(value) : null;
  };

  const getBookingModeLabel = (booking) => {
    const mode = String(booking?.bookingMode ?? booking?.booking_mode ?? 'normal').toLowerCase();
    return mode === 'proxy' ? 'Proxy' : 'Normal';
  };

  const getOccupancySummary = (booking) => {
    const occupants = resolveOccupantCount(booking);
    const capacity = resolveRoomCapacity(booking);

    if (capacity) {
      return `${occupants}/${capacity} occupants`;
    }

    return `${occupants} occupant${occupants === 1 ? '' : 's'}`;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="space-y-6">
        {isCaretaker && !canManageBookings && (
          <div className="p-4 bg-amber-50 border border-amber-200 rounded-lg text-sm text-amber-800">
            You are viewing bookings as a caretaker. You need approve and/or cancel booking permissions to perform actions.
          </div>
        )}

        <AddBookingModal
          isOpen={showAddBookingModal}
          onClose={() => setShowAddBookingModal(false)}
          onBookingAdded={() => {
            setShowAddBookingModal(false);
            refreshLandlordMutationViews();
            fetchBookings();
            fetchStats();
          }}
        />

        {/* Stats */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {loading ? [...Array(4)].map((_, i) => <SkeletonStatCard key={i} />) : (
            <>
              <div className="relative overflow-hidden bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-300 dark:border-gray-700">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs font-bold text-gray-500 dark:text-gray-500 uppercase tracking-wider mb-2">Total Bookings</p>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white mt-2">{stats.total}</p>
                  </div>
                  <div className="w-10 h-10 bg-gray-50 dark:bg-gray-900/20 rounded-lg flex items-center justify-center">
                    <Calendar className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  </div>
                </div>
              </div>
              <div className="relative overflow-hidden bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-300 dark:border-gray-700">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs font-bold text-gray-500 dark:text-gray-500 uppercase tracking-wider mb-2">Confirmed</p>
                    <p className="text-2xl font-bold text-green-600 mt-2">{stats.confirmed}</p>
                  </div>
                  <div className="w-10 h-10 bg-green-50 dark:bg-green-900/20 rounded-lg flex items-center justify-center">
                    <CheckCircle className="w-5 h-5 text-green-600 dark:text-green-400" />
                  </div>
                </div>
              </div>
              <div className="relative overflow-hidden bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-300 dark:border-gray-700">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs font-bold text-gray-500 dark:text-gray-500 uppercase tracking-wider mb-2">Pending</p>
                    <p className="text-2xl font-bold text-yellow-600 mt-2">{stats.pending}</p>
                  </div>
                  <div className="w-10 h-10 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg flex items-center justify-center">
                    <Clock className="w-5 h-5 text-yellow-600 dark:text-yellow-400" />
                  </div>
                </div>
              </div>
              <div className="relative overflow-hidden bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-300 dark:border-gray-700">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs font-bold text-gray-500 dark:text-gray-500 uppercase tracking-wider mb-2">Completed</p>
                    <p className="text-2xl font-bold text-blue-600 mt-2">{stats.completed}</p>
                  </div>
                  <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 rounded-lg flex items-center justify-center">
                    <Check className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                  </div>
                </div>
              </div>
            </>
          )}
        </div>

        {/* Search & Filters */}
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-300 dark:border-gray-700 flex flex-col lg:flex-row gap-4 lg:items-center">
          <div className="relative flex-1 w-full">
            {filterStatus !== 'extensions' && filterStatus !== 'transfers' && (
              <>
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500 dark:text-gray-500" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by name, room, property..."
                  className="w-full pl-10 pr-4 py-2.5 border border-gray-200 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent transition-all dark:bg-gray-700 dark:text-white outline-none text-sm"
                />
              </>
            )}
          </div>
          <div className="flex gap-2 overflow-x-auto pb-2 lg:pb-0 no-scrollbar w-full lg:w-auto">
            {['all', 'confirmed', 'pending_reservation', 'reserved', 'pending', 'completed', 'cancelled', 'extensions', 'transfers'].map((s) => (
              <button
                key={s}
                onClick={() => setFilterStatus(s)}
                className={`flex-1 lg:flex-none px-4 py-2 rounded-lg text-xs md:text-sm font-bold transition-all whitespace-nowrap ${filterStatus === s ? 'bg-green-600 text-white shadow-md shadow-green-500/20' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'}`}
              >
                {s === 'extensions' ? 'Extensions' : s === 'transfers' ? 'Transfers' : s === 'pending_reservation' ? 'Pending Res.' : s.charAt(0).toUpperCase() + s.slice(1)}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-2 ml-auto">
            <button
              onClick={handleRefresh}
              disabled={loading}
              title="Refresh"
              className="p-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center disabled:opacity-50 shadow-md shadow-blue-500/20"
            >
              {loading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <RefreshCw className="w-5 h-5" />
              )}
            </button>
          </div>
        </div>

        {/* Table / Extensions List */}
        {filterStatus === 'extensions' ? (
          <ExtensionRequestsList
            requests={extensionRequests}
            loading={loadingExtensions}
            onHandle={handleHandleExtension}
          />
        ) : filterStatus === 'transfers' ? (
          <TransferRequestsList
            requests={transferRequests}
            loading={loadingTransfers}
            onHandle={handleHandleTransfer}
          />
        ) : (
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-300 dark:border-gray-700 overflow-hidden">
            <div className="overflow-x-auto no-scrollbar">
              <table className="w-full text-left">
                <thead className="bg-gray-50 dark:bg-gray-700 text-xs font-bold uppercase text-gray-500 dark:text-gray-400 tracking-wider">
                  <tr>
                    <th className="px-6 py-4">Guest</th>
                    <th className="px-6 py-4">Property/Room</th>
                    <th className="px-6 py-4">Dates</th>
                    <th className="px-6 py-4">Amount</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                  {loading ? [...Array(5)].map((_, i) => <SkeletonTableRow key={i} columns={6} />) :
                    filteredBookings.length === 0 ? (
                      <tr>
                        <td colSpan="6" className="px-6 py-12 text-center text-gray-500 dark:text-gray-400 font-medium">
                          No bookings found matching your search.
                        </td>
                      </tr>
                    ) : (
                      filteredBookings.map((b) => (
                        <tr key={b.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                          <td className="px-6 py-4">
                            <p className="font-bold text-gray-900 dark:text-white">{b.guestName}</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">{b.email}</p>
                          </td>
                          <td className="px-6 py-4">
                            <p className="font-bold text-gray-900 dark:text-white">{b.propertyTitle}</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">Room {b.roomNumber}</p>
                            {String(b.booking_mode || b.bookingMode || 'normal').toLowerCase() === 'proxy' && (
                              <p className="text-[11px] text-gray-500 dark:text-gray-400 font-medium mt-1">
                                Mode: {getBookingModeLabel(b)} · Beds: {resolveBedCount(b)} · {getOccupancySummary(b)}
                              </p>
                            )}
                          </td>
                          <td className="px-6 py-4 text-sm font-medium text-gray-700 dark:text-gray-300">
                            <p>{formatDate(b.checkIn)}</p>
                            <p className="text-xs text-gray-500 dark:text-gray-400">to {formatDate(b.checkOut)}</p>
                          </td>
                          <td className="px-6 py-4 text-sm font-bold text-gray-900 dark:text-white">
                            <PriceRow amount={b.amount} />
                          </td>
                          <td className="px-6 py-4">
                            <span className={`px-2 py-2 rounded-md text-[10px] font-bold uppercase ${getStatusColor(b.status)}`}>{b.status}</span>
                          </td>
                          <td className="px-6 py-4">
                            <button onClick={() => handleOpenDetailModal(b)} className="text-green-600 dark:text-green-500 hover:text-green-800 dark:hover:text-green-400 text-xs font-bold uppercase flex items-center gap-2 transition-colors">
                              <Eye className="w-3.5 h-3.5" /> View
                            </button>
                          </td>
                        </tr>
                      ))
                    )
                  }
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Detail Modal */}
      {showDetailModal && selectedBooking && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto border border-gray-100 dark:border-gray-700 shadow-2xl animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center sticky top-0 bg-white dark:bg-gray-800 z-10">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">Booking Details</h2>
              <button onClick={closeDetailModal} className="p-2.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors">
                <X className="w-6 h-6 text-gray-500 dark:text-gray-500" />
              </button>
            </div>
            <div className="p-6 space-y-6">
              <div className="grid grid-cols-2 gap-6 bg-gray-50 dark:bg-gray-700/50 p-4 rounded-xl border border-gray-100 dark:border-gray-700">
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400 uppercase font-bold tracking-wider mb-2">{selectedBooking.contract_mode === 'daily' ? 'Check-In' : 'Move-In'}</p>
                  <p className="font-bold text-lg text-gray-900 dark:text-white">{formatDate(selectedBooking.checkIn)}</p>
                </div>
                <div>
