                className="flex-1 px-4 py-4 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-xl font-bold hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors disabled:opacity-50"
              >
                Go Back
              </button>
              <button
                onClick={handleCancelConfirm}
                disabled={processing}
                className="flex-1 px-4 py-4 bg-red-600 text-white rounded-xl font-bold hover:bg-red-700 transition-colors shadow-lg shadow-red-500/30 flex items-center justify-center gap-2 disabled:opacity-50 active:scale-[0.98]"
              >
                {processing ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Processing...
                  </>
                ) : (
                  'Confirm Cancel'
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Finalize Checkout Confirmation Modal */}
      {showFinalizeModal && selectedBooking && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[115] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl max-w-md w-full p-6 shadow-2xl border border-gray-100 dark:border-gray-700 animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">Finalize Checkout</h3>
              <button
                onClick={() => setShowFinalizeModal(false)}
                className="p-2.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors"
                disabled={processing}
              >
                <X className="w-6 h-6 text-gray-500 dark:text-gray-500" />
              </button>
            </div>

            <div className="bg-blue-50 dark:bg-blue-900/20 rounded-xl p-4 mb-6 border border-blue-100 dark:border-blue-900/30">
              <p className="text-sm text-blue-800 dark:text-blue-300 font-bold mb-2">Booking: {selectedBooking.guestName}</p>
              <p className="text-xs text-blue-700 dark:text-blue-400 font-medium">Ref: {selectedBooking.bookingReference}</p>
              <p className="text-xs text-blue-700 dark:text-blue-400 font-medium mt-2">
                This will close the current stay and mark checkout as completed based on payment status.
              </p>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setShowFinalizeModal(false)}
                className="flex-1 px-5 py-3 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-xl hover:bg-gray-50 dark:hover:bg-gray-700 font-bold transition-all"
                disabled={processing}
              >
                Cancel
              </button>
              <button
                onClick={() => handleFinalizeCheckout(selectedBooking.id)}
                disabled={processing}
                className="flex-1 px-5 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all shadow-lg shadow-blue-500/20 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {processing ? (
                  <span className="flex items-center justify-center gap-2">
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Finalizing...
                  </span>
                ) : (
                  'Confirm Checkout'
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Convert Occupant Modal */}
      {showConvertModal && occupantToConvert && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[120] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl max-w-md w-full p-6 shadow-2xl border border-gray-100 dark:border-gray-700 animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">Register as Tenant</h3>
              <button
                onClick={() => {
                  setShowConvertModal(false);
                  setOccupantToConvert(null);
                  setConvertEmail('');
                }}
                className="p-2.5 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full transition-colors"
                disabled={processing}
              >
                <X className="w-6 h-6 text-gray-500 dark:text-gray-500" />
              </button>
            </div>

            <div className="bg-indigo-50 dark:bg-indigo-900/20 rounded-xl p-4 mb-6 border border-indigo-100 dark:border-indigo-900/30">
              <p className="text-sm text-indigo-800 dark:text-indigo-300 font-bold mb-2">
                Occupant: {[occupantToConvert.first_name, occupantToConvert.last_name].filter(Boolean).join(' ') || 'Unnamed'}
              </p>
              <p className="text-xs text-indigo-700 dark:text-indigo-400 font-medium">
                This will create a tenant account and send them an initial login email.
              </p>
            </div>

            <div className="space-y-4 mb-6">
              <div>
                <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">
                  Email Address <span className="text-red-500">*</span>
                </label>
                <input
                  type="email"
                  value={convertEmail}
                  onChange={(e) => setConvertEmail(e.target.value)}
