      const original = (selectedRoom?.images || []).find(img => 
        (typeof img === 'string' && img === imageToRemove) || 
        (img && typeof img === 'object' && (img.image_url === imageToRemove || img.url === imageToRemove))
      );
      if (original && original.id) {
